"""Avoidance / negation detector for layers.15.mlp.down_proj component 2327.

What the component does: it goes strongly negative on words that avoid, prevent, remove or
reduce something ("avoid", "prevent", "minimize", "eliminate", "reduce", "stop"), more weakly
on plain negation ("not", "no", "never", "without", "n't"), and it also dips on the short
linking word right after one of those ("reduce *the* risk", "free *of* danger", "instead
*of*", "not *to*"). Elsewhere it is near zero. Its positive side (purpose "to" as in "in order
to", "just to") is weak and is not modelled here.

This program only reads the current token and the one before it (same document), so it is
stateless. It is a rough rule: the component's large swings depend on the wider sentence,
which the rule does not see.
"""

READS = ()

AVOID = {
    "avoid", "avoiding", "avoids", "avoided", "prevent", "prevents", "preventing",
    "prevented", "prevention", "reduce", "reduces", "reducing", "reduced", "reduction",
    "minimize", "minimise", "minimizing", "eliminate", "eliminating", "elimination",
    "remove", "removing", "removal", "stop", "stopping", "halt", "block", "lessen",
    "decrease", "limit", "mitigate", "overcome", "refrain", "cease", "exclude", "excluding",
    "protect", "protecting", "减少", "避免", "防止",
}
NEGATE = {
    "not", "no", "never", "without", "free", "instead", "absence", "lack", "less", "fewer",
    "nor", "non", "don", "won", "can't", "'t", "’t", "n't", "sans", "без", "не", "nicht",
    "kein", "pas", "nie", "nu", "ne", "不", "不要", "别",
}
LINK = {
    "the", "of", "to", "from", "for", "any", "than", "in", "a", "an", "its", "their", "his",
    "her", "your", "all", "with",
}


def _word(token):
    return token.strip().lower()


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    prev = ""
    if len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = _word(prefix.token_strings[-2])
    if word in AVOID:
        value = -2.3
    elif word in NEGATE:
        value = -1.1
    elif prev in AVOID:
        value = -2.5 if word in LINK else -0.9
    elif prev in NEGATE:
        value = -1.1 if word in LINK else -0.6
    else:
        value = 0.0
    return carry, value

"""Component p-82af68dd@100000/layers.15.mlp.down_proj:2340.

Fires on the words of an embedded clause that a complementizer opens. The strongest
opener is "that" right after a verb ("shows that", "notes that", "concluded that"); the
activation is highest on the "that" itself and on the first word after it (the subject or
auxiliary of the clause, as in "that [there] [are]"), and fades over the next few words.
Weaker openers: "that" after a noun or a verb of saying/thinking two or three words back
(a relative or a noun complement, "the fact that"), "how", "what", "whether", "if" after a
verb, and "sure" in "make sure [they] ...". "That" after a noun with no such verb is a
relative pronoun and barely fires.

The prediction for a position is the largest profile value of any opener at an offset from
-1 (the opener itself) to +4 words. It reads only the words up to the current position.
"""
import wordnet

READS = ()

# Activation by offset k from the opener: index 0 is k = -1 (the opener itself),
# index 1 is the word right after it, and so on up to four words later.
TRIGGER_PROFILE = {
    "that_after_verb": [1.8, 2.6, 1.7, 1.2, 0.5, 0.4],
    "that_after_noun": [0.6, 1.3, 0.7, 0.4, 0.3, 0.1],
    "that_after_noun_cog": [1.0, 1.9, 1.2, 0.8, 0.4, 0.2],
    "wh_after_verb": [1.4, 1.4, 0.8, 0.5, 0.3, 0.1],
    "sure": [0.5, 1.8, 1.2, 0.8, 0.4, 0.2],
}
WH_WORDS = {"how", "what", "whether", "if"}
SAY_THINK = {"verb.communication", "verb.cognition"}


def _is_verb(word):
    return word.isalpha() and "verb" in wordnet.parts_of_speech(word)


def _saying_or_thinking_verb_near(toks, j):
    """A verb of saying or thinking 2 or 3 words before toks[j]."""
    for k in (2, 3):
        if j - k >= 0 and toks[j - k].isalpha() and (wordnet.categories(toks[j - k], "verb") & SAY_THINK):
            return True
    return False


def _opener_kind(toks, j):
    """Which kind of clause opener toks[j] is, or None."""
    if j < 1:
        return None
    if toks[j] == "that":
        if _is_verb(toks[j - 1]):
            return "that_after_verb"
        if _saying_or_thinking_verb_near(toks, j):
            return "that_after_noun_cog"
        return "that_after_noun"
    if toks[j] in WH_WORDS and _is_verb(toks[j - 1]):
        return "wh_after_verb"
    if toks[j] == "sure":
        return "sure"
    return None


def step(carry, prefix, upstream):
    toks = [s.strip().lower() for s in prefix.token_strings]
    docs = prefix.document_ids
    t = prefix.position
    best = 0.0
    for k in range(-1, 5):  # the opener is at t - k - 1: k = -1 is t itself
        j = t - k - 1
        if j < 0 or docs[j] != docs[t]:
            continue
        kind = _opener_kind(toks, j)
        if kind:
            best = max(best, TRIGGER_PROFILE[kind][k + 1])
    return carry, best

"""Opening prepositions of introductory adverbial phrases.

A preposition that opens a phrase setting the scene for the clause ("In the case of",
"For example", "On the other hand", "But in", "which in", "Since in") is strongly active;
one that attaches to a noun or verb ("experience in", "born in", "with") is weak. The words
that continue an opener share it: the determiner or quantifier right after ("In the",
"In most"), and the noun of a fixed phrase ("In the case of"). Mostly this is a
preposition-and-context rule, and it explains about 15% of the activation's variance.
"""
from collections.abc import Mapping

READS: tuple[str, ...] = ()

# How strongly each preposition opens an adverbial phrase: its base strength.
STRONG = {"in", "for", "at", "during", "under"}
MEDIUM = {"on", "among", "within", "when", "if", "pour", "bei", "dans", "en", "im"}
WEAK = {"with", "by", "from", "to", "of", "over", "into", "through", "between", "about", "as"}
BASE = {**{w: 1.4 for w in STRONG}, **{w: 0.8 for w in MEDIUM}, **{w: 0.2 for w in WEAK}}
# Words after which a preposition starts a clause-level phrase (a sentence break, a comma,
# or a connective). There the preposition is boosted about threefold.
BREAKS = {".", ";", ":", "!", "?", "\n", "", ",", '"', "("}
CONNECTIVES = {"but", "so", "that", "which", "because", "since", "though", "however", "and",
               "or", "while", "where", "whereas", "although", "maybe", "perhaps", "thus",
               "therefore", "yet", "unless", "wait", "then", "as", "if", "when"}
BOOST = 3.3
DETERMINERS = {"the", "this", "a", "an", "its", "our", "their", "his", "her", "my", "your"}
QUANTIFIERS = {"most", "some", "many", "certain", "such", "other", "both", "all", "any", "each"}
# Nouns that complete a fixed opener: "in the case of", "in this instance", "for example".
FRAME_NOUNS = {"case", "cases", "instance", "example", "examples", "particular"}
# Function words that do not take a complement preposition like a noun does.
FUNCTION = DETERMINERS | QUANTIFIERS | CONNECTIVES | set(BASE) | BREAKS | {
    "is", "was", "are", "were", "be", "been", "it", "he", "she", "they", "we", "you", "i",
    "not", "no", "very", "more", "also", "only", "just", "there", "here", "who", "what"}


def _word(s):
    return s.strip().lower()


def _opener(word, before):
    """Activation of preposition `word` after the word `before`."""
    value = BASE[word]
    return value * BOOST if before in BREAKS or before in CONNECTIVES else value


def step(carry, prefix, upstream: Mapping):
    t = prefix.position
    docs = prefix.document_ids

    def word(k):
        # the word k places back, or "" before this document's first token
        if k > t or docs[t - k] != docs[t]:
            return ""
        return _word(prefix.token_strings[t - k])

    cur, prev, prev2, prev3 = word(0), word(1), word(2), word(3)
    if cur == "of":
        # "of" after an ordinary noun or verb is slightly negative
        ordinary = prev.isalpha() and prev not in FUNCTION
        return carry, -0.4 if ordinary else 0.0
    if cur in BASE:
        return carry, _opener(cur, prev)
    if prev in BASE and (cur in DETERMINERS or cur in QUANTIFIERS):
        return carry, 0.7 * _opener(prev, prev2)
    if cur in FRAME_NOUNS and (prev in DETERMINERS or prev in QUANTIFIERS) and prev2 in BASE:
        return carry, _opener(prev2, prev3)
    return carry, 0.0

"""Activation of one MLP unit in layer 15 (down_proj component 2365), predicted from the current token.

The component reads the MLP's hidden state and writes a direction that, through the tied
embedding, promotes words like "businessman", "wealthy", "holding company" and "rich household".
Its activation is high on the word for a wealthy, powerful or high-ranking person (businessman,
wealthy, billionaire, politician, influential, lord, prince, cardinal) and on wealth words
(wealth, fortune, prosperity), and low (negative) on words that describe ordinary or young people
(man, woman, girl, orphan, student) and on age words (years old, born, 岁).

The program predicts that value from the current token only. It explains very little of the
variance, because most of the activation is spread over ordinary tokens with context-driven values.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

# People who hold wealth, power or rank: strong positive.
ROLE_WORDS = {
    "wealthy", "billionaire", "millionaire", "businessman", "businesswoman", "entrepreneur",
    "tycoon", "founder", "politician", "influential", "prominent", "ruler", "leaders", "prince",
    "princess", "duke", "earl", "lord", "noble", "royal", "royalty", "cardinal", "patron",
    "sponsor", "king", "queen", "emperor", "baron", "elite", "merchant",
}
# Wealth and property words: weaker positive.
WEALTH_WORDS = {
    "wealth", "riches", "fortune", "prosperity", "prosperous", "money", "rich", "shareholder",
    "owned", "owner", "investor", "power", "powerful",
}
# Ordinary or young people, and age words: negative.
YOUNG_WORDS = {"man", "woman", "girl", "boy", "orphan", "student", "teenager", "graduate", "born"}
CHINESE_WEALTH = {"财富", "富", "富豪", "土豪", "老板", "商人", "集团", "股东", "权力"}
CHINESE_YOUNG = {"岁", "歲", "大学生"}


def value_of(token: str) -> float:
    word = token.strip().lower()
    if word in ROLE_WORDS:
        return 1.5
    if word in WEALTH_WORDS:
        return 0.75
    if word in YOUNG_WORDS:
        return -0.5
    if token in CHINESE_WEALTH:
        return 1.0
    if token in CHINESE_YOUNG:
        return -0.5
    return -0.04


def step(carry, prefix, upstream: Mapping):
    return carry, value_of(prefix.token_strings[-1])
